edits.before:
`<div class="gb-range-band" aria-label="Range position">
      <div class="gb-range-band-track">
        ${lowZoneWidth ? `<div class="gb-range-band-zone gb-range-band-zone-low" style="left:0%;width:${lowZoneWidth}%"></div>` : ''}
        ${highZoneWidth ? `<div class="gb-range-band-zone gb-range-band-zone-high" style="left:${optRight}%;width:${highZoneWidth}%"></div>` : ''}
        ${optWidth ? `<div class="gb-range-band-opt" style="left:${optLeft}%;width:${optWidth}%"></div>` : ''}
      </div>
      <div class="gb-range-band-dot gb-range-band-dot-${escapeAttr(latestStatus)}" style="left:${dot}%"></div>
      <div class="gb-range-band-scale"><span>${escapeHTML(formatValue(min))}</span><span>${escapeHTML(formatValue(max))}</span></div>
    </div>`

edits.after:
renderMarkerDetailRange({ kind: "edited-badge", label: `${badgeTitle}`, title: `${badgeTitle}`,
      actions: `${markerDetailActionAttrs('revert-ref-range', { id, type })}`, text: `${badgeLabel}`,
    })

renderMarkerDetailHistory({ kind: "value-note", editActions: `${markerDetailActionAttrs('edit-value-note', { id, date: actionDate })}`,
            text: `${escapeHTML(valueNote)}`, deleteActions: `${markerDetailActionAttrs('delete-value-note', { id, date: actionDate })}`,
          })

renderMarkerDetailHistory({ kind: "last-values", actions: `${markerDetailActionAttrs('show-detail-modal', { id, scrollToHistory: true })}`,
      count: `${MARKER_HISTORY_DEFAULT_CAP}`,
    })

renderMarkerDetailHistory({ kind: "trend", direction: `${dir}`, change: `${Math.abs(ch).toFixed(2)}`, unit: `${escapeHTML(marker.unit)}`, sign: `${ch>0?"+":""}`,
      percentage: `${pct}`, firstDate: `${dates[f.i]}`, lastDate: `${dates[l.i]}`,
    })
